ember 2010 data gap.\n","signature":""},{"type":"toolRequest","id":"call_8f3ee77308d74311b8eabdb5","toolCall":{"status":"success","value":{"name":"shell","arguments":{"command":"ls -la /app/"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
